#!/usr/bin/env bash
# shellcheck shell=bash
# Generated by kwisatz tasks/setup-gufo-strix-halo-qwen38-27b.sh from
# templates/gufo-strix-halo-qwen38-27b/gufo-serve.sh — do not edit it here.
#
# What this is: the runtime contract of the Gufo Qwen3.8-27B engine on
# AMD Strix Halo. llama-swap execs it as the model's `serve.cmd`, and it MUST
# block for the container's lifetime so llama-swap can track (and stop) the
# model. Hence `docker run --rm` without -d, and hence `exec`.
#
# Every setting lives in ${STATE_DIR}/.env — see serve.env in the template
# directory for what each key means. Absolute paths everywhere, because
# llama-swap execs this from an unpredictable working directory.
#
# There is deliberately no `|| true` anywhere: a serve script that exits 0
# after a failed start is how llama-swap ends up "serving" a model that is not
# there.
set -eu

# Absolute paths everywhere: llama-swap execs this from an unpredictable
# working directory, and STATE_DIR is rendered once here so the rest of the
# script can use the variable (and a relocated service dir is a re-run, not an
# edit).
STATE_DIR="${STATE_DIR_PATH}"

if [[ ! -r "${STATE_DIR}/.env" ]]; then
  echo "gufo-serve.sh: cannot read ${STATE_DIR}/.env — re-run tasks/setup-gufo-strix-halo-qwen38-27b.sh" >&2
  exit 1
fi
# shellcheck source=/dev/null
source "${STATE_DIR}/.env"

# ── Defaults that only exist so a hand-edited .env cannot crash this ──────────
PORT="${PORT:-${GUFO_PORT_DEFAULT}}"
CONTAINER_NAME="${CONTAINER_NAME:-${GUFO_CONTAINER_NAME}}"
HF_CACHE="${HF_CACHE:-${HF_CACHE_DEFAULT}}"
GUFO_IMAGE="${GUFO_IMAGE:-${GUFO_IMAGE_DEFAULT}}"
GUFO_MODEL_NAME="${GUFO_MODEL_NAME:-${GUFO_MODEL_NAME_DEFAULT}}"
CONTAINER_RUNTIME="${CONTAINER_RUNTIME:-docker}"
HSA_OVERRIDE_GFX_VERSION="${HSA_OVERRIDE_GFX_VERSION:-11.5.1}"
HSA_ENABLE_SDMA="${HSA_ENABLE_SDMA:-0}"
GUFO_SHM_SIZE="${GUFO_SHM_SIZE:-16g}"
GUFO_CONTEXT_LENGTH="${GUFO_CONTEXT_LENGTH:-${GUFO_CONTEXT_LENGTH_DEFAULT}}"

# ── Snapshot ordering ───────────────────────────────────────────────────────
# Newest-first, by mtime. `ls -dt` would do it too, but ls output is not meant
# to be parsed and find's is: -printf gives us the timestamp and the path on
# one line, and the rest is a sort. A hand-placed or hand-updated snapshot then
# wins on the same rule as a downloaded one, instead of on name order.
snapshots_newest_first() {
  find "$1" -maxdepth 1 -mindepth 1 -type d -printf '%T@ %p\n' 2>/dev/null \
    | sort -rn | sed 's/^[0-9.]* //'
}

# ── Shard sets ───────────────────────────────────────────────────────────────
# A checkpoint is either one file or N files named <prefix>-00001-of-00004.gguf.
# The file name carries the count, so "is the whole thing here?" is free to ask,
# and asking is the point: the engine opens the file it is given, reads
# split.count out of that file's metadata and then looks its siblings up by
# name, so a partial set is a load failure whose error says nothing about the
# missing parts — which reads as "the model is broken" rather than "run the
# download again".
#
#   shard_set_state <snapshot-dir> <pattern>
#     -> "OK<TAB><first shard, relative to the snapshot>"
#     -> "PARTIAL<TAB><which file is missing>"
#     -> "NONE<TAB>"
#
# First shard, not first match: handing the engine shard 2 of a 4-part model
# would load the wrong tensors in silence, because the loader trusts the index
# it is handed. `sort` gets there by luck (zero-padded names), so the index is
# matched explicitly and the sort order is only the fallback for checkpoints
# that are not split at all.
shard_set_state() {
  local snap="$1" pattern="$2"
  local -a files=()
  mapfile -t files < <(compgen -G "${snap}/${pattern}" 2>/dev/null | sort)
  if [[ ${#files[@]} -eq 0 ]]; then
    printf 'NONE\t\n'
    return 0
  fi
  local first base prefix iw cw total n f dir
  first="${files[0]}"
  for f in "${files[@]}"; do
    base="${f##*/}"
    if [[ "$base" =~ ^(.*-)0*1-of-[0-9]+\.gguf$ ]]; then
      first="$f"
      break
    fi
  done
  # Sibling shards sit next to the file the glob matched, which may be a
  # checkpoint subdirectory rather than the snapshot root.
  dir="${first%/*}"
  base="${first##*/}"
  if [[ ! "$base" =~ ^(.*-)([0-9]+)-of-([0-9]+)\.gguf$ ]]; then
    printf 'OK\t%s\n' "${first#"$snap"/}"
    return 0
  fi
  prefix="${BASH_REMATCH[1]}"
  iw="${#BASH_REMATCH[2]}"
  cw="${#BASH_REMATCH[3]}"
  total=$((10#${BASH_REMATCH[3]}))
  for ((n = 1; n <= total; n++)); do
    f="${dir}/${prefix}$(printf '%0*d' "$iw" "$n")-of-$(printf '%0*d' "$cw" "$total").gguf"
    if [[ ! -e "$f" ]]; then
      printf 'PARTIAL\t%s is missing from %s (the glob found %d of %d)\n' \
        "$f" "$snap" "${#files[@]}" "$total"
      return 0
    fi
  done
  printf 'OK\t%s\n' "${first#"$snap"/}"
}

# ── Resolve the checkpoint ──────────────────────────────────────────────────
# Newest snapshot that holds a COMPLETE shard set for this pattern. Newest, not
# newest-by-name: a hand-updated repo leaves the old snapshot in place, and HF's
# "latest" pointer is a file this script does not have to trust. A snapshot that
# is only part-fetched is passed over in favour of an older complete one, and
# said out loud — serving the older weights is a decision the operator should
# see, and serving half a checkpoint is not a decision at all.
#
# The cache-directory fragment ("unsloth--Qwen3.8-Flash-Next-GGUF") is rendered
# here rather than derived from a repo id at runtime: a ${VARIABLE//\/--} inside
# this file would be substituted by envsubst before bash ever saw it, turning
# the parameter expansion into a syntax accident.
model_dir="${HF_CACHE}/hub/models--${GUFO_MODEL_CACHE_NAME}"
snapshot=""
shard=""
partial=""
kind=""
rest=""
while IFS= read -r d; do
  out="$(shard_set_state "$d" "${GUFO_SHARD_PATTERN}")"
  IFS=$'\t' read -r kind rest <<<"$out"
  case "$kind" in
  OK)
    snapshot="$d"
    shard="$rest"
    break
    ;;
  PARTIAL)
    if [[ -z "$partial" ]]; then
      partial="$rest"
    fi
    ;;
  esac
done < <(snapshots_newest_first "${model_dir}/snapshots")

if [[ -z "$snapshot" ]]; then
  if [[ -n "$partial" ]]; then
    printf 'gufo-serve.sh: the checkpoint is only part-fetched: %s\n' "$partial" >&2
    printf 'gufo-serve.sh: re-run  bash %s/gufo-prepare.sh  — hf finishes what it started\n' "${STATE_DIR}" >&2
  else
    printf 'gufo-serve.sh: no file matching %s in any snapshot under %s/snapshots\n' \
      "${GUFO_SHARD_PATTERN}" "${model_dir}" >&2
    printf 'gufo-serve.sh: download it with  bash %s/gufo-prepare.sh   or re-run the setup task\n' "${STATE_DIR}" >&2
  fi
  exit 1
fi
if [[ -n "$partial" ]]; then
  printf 'gufo-serve.sh: NOTE — a newer snapshot is part-fetched (%s); serving the complete older snapshot under %s\n' "$partial" "${snapshot}"
fi

# ── Engine arguments ─────────────────────────────────────────────────────────
gufo_args=(
  serve
  llm
  --host 127.0.0.1
  --port "${PORT}"
  --model "/models/${shard}"
  # --served-model-name must equal the catalog id, or the model field Gufo
  # echoes back will disagree with what llama-swap was asked for.
  --served-model-name "${GUFO_MODEL_NAME}"
  # --context, NOT --context-length. Checked against the engine itself: the
  # option table of v0.8.1 (src/cli/serve/serve.cpp) registers "-c/--context"
  # and has no --context-length at all, and docs/CLI.md lists `context` under
  # "Size and memory". Gufo rejects unknown options with `Error: unknown
  # option` and exit 2, so a wrong flag name kills the container before it ever
  # binds a port — that is a failed load, not a slow one. The other flags below
  # were checked the same way: --host, --port, --model, --served-model-name,
  # --sessions, --cache-disk-staging-bytes, --speculative and the draft-path
  # flags are spelled exactly as the binary spells them.
  --context "${GUFO_CONTEXT_LENGTH}"
)
if [[ -n "${GUFO_SESSIONS:-}" ]]; then
  gufo_args+=(--sessions "${GUFO_SESSIONS}")
fi
if [[ -n "${GUFO_CACHE_DISK_STAGING_BYTES:-}" && "${GUFO_CACHE_DISK_STAGING_BYTES}" != "0" ]]; then
  gufo_args+=(--cache-disk-staging-bytes "${GUFO_CACHE_DISK_STAGING_BYTES}")
fi
if [[ -n "${GUFO_GPU_MEMORY_UTILIZATION:-}" ]]; then
  gufo_args+=(--gpu-memory-utilization "${GUFO_GPU_MEMORY_UTILIZATION}")
fi
if [[ -n "${GUFO_EXTRA_ARGS:-}" ]]; then
  # Word splitting is the point: this key is a flag list, not one flag.
  # shellcheck disable=SC2206
  extra=(${GUFO_EXTRA_ARGS})
  gufo_args+=("${extra[@]}")
fi

# ── Container arguments ──────────────────────────────────────────────────────
run_args=(
  run
  --rm
  --name "${CONTAINER_NAME}"
  # Host network: Gufo's API must be reachable at a fixed loopback port that
  # llama-swap's proxy already knows about. A bridge network would need a
  # published port, which is one more thing to keep in sync with the entry.
  --network host
  --device /dev/kfd
  --device /dev/dri
  # The model is paged into the GPU aperture, not copied; without unlimited
  # memlock the load fails partway with a "Resource temporarily unavailable".
  --ulimit memlock=-1
  --shm-size "${GUFO_SHM_SIZE}"
  -e "HSA_OVERRIDE_GFX_VERSION=${HSA_OVERRIDE_GFX_VERSION}"
  -e "HSA_ENABLE_SDMA=${HSA_ENABLE_SDMA}"
  # Read-only by design. The engine gets no write access to the weights.
  -v "${snapshot}:/models:ro"
  -w /models
)
if [[ -d "${STATE_DIR}/logs" ]]; then
  run_args+=(-v "${STATE_DIR}/logs:/var/log/gufo")
fi
# ── Sidecar / speculation ────────────────────────────────────────────────────
# A draft model lives in another repo (or another subdirectory of the same
# one), so it gets its own read-only mount rather than being copied into
# /models — copying would put a second ~2 GB under the service's state dir and
# break the "weights live in the user's cache" rule.
#
# Upstream's validated recipes name BOTH the backend and the draft path:
#
#   27B         --speculative dflash2 --dflash-model <Q4_K_M draft>
#   Flash-Next  --speculative mtp     --mtp-model    <shared-Q8_0 sidecar>
#
# and the backend flag on its own is a startup error rather than a fallback:
# "Error: DFlash2 requires --dflash-model and --min-draft-tokens 1", exit 2. So
# the wrapper resolves the draft file and appends the flag that names it, while
# GUFO_SPEC_ARGS carries the switch. One .env line (GUFO_SPEC_ARGS=) turns
# speculation off; no file edit, same as every other lever here.
#
# What is NOT here is a GUFO_DRAFT_MODEL environment variable. The engine reads
# no such key — its only two environment inputs are HOME and XDG_CACHE_HOME —
# and publishing a path the engine never opens is precisely how "speculation is
# on" turns into "speculation is off, quietly, and nobody noticed".

# Newest snapshot that holds the draft, and the draft's path inside it.
draft_snapshot=""
draft_rel=""
if [[ -n "${GUFO_DRAFT_REPO:-}" && -n "${GUFO_DRAFT_PATTERN:-}" ]]; then
  draft_dir_hf="${HF_CACHE}/hub/models--${GUFO_DRAFT_REPO//\//--}"
  while IFS= read -r d; do
    if compgen -G "${d}/${GUFO_DRAFT_PATTERN}" >/dev/null 2>&1; then
      draft_snapshot="$d"
      break
    fi
  done < <(snapshots_newest_first "${draft_dir_hf}/snapshots")
  if [[ -n "$draft_snapshot" ]]; then
    # first match, deterministically: a glob inside a flag value would be the
    # engine's problem, not ours. Kept RELATIVE to the snapshot because a
    # sidecar that lives in a subdirectory (Flash-Next keeps them under MTP/)
    # has to keep that path through the mount.
    draft_file="$(compgen -G "${draft_snapshot}/${GUFO_DRAFT_PATTERN}" | sort | head -1)"
    draft_rel="${draft_file#"$draft_snapshot"/}"
  fi
fi

if [[ -z "${GUFO_SPEC_ARGS:-}" ]]; then
  if [[ -n "$draft_rel" ]]; then
    printf 'gufo-serve.sh: draft /draft/%s cached — speculation is off, set GUFO_SPEC_ARGS to use it\n' \
      "$draft_rel"
  fi
else
  # Word splitting is the point: this key is a flag list, not one flag.
  # shellcheck disable=SC2206
  spec=(${GUFO_SPEC_ARGS})
  # Which backend did this switch turn on? The path flag belongs to the
  # backend, so it is derived rather than guessed at by the operator.
  backend=""
  next_is_backend=0
  for arg in "${spec[@]}"; do
    if [[ "$next_is_backend" == "1" ]]; then
      backend="$arg"
      break
    fi
    if [[ "$arg" == "--speculative" ]]; then
      next_is_backend=1
    fi
  done
  path_flag=""
  case "$backend" in
  dflash2) path_flag="--dflash-model" ;;
  mtp) path_flag="--mtp-model" ;;
  dspark) path_flag="--dspark-model" ;;
  esac
  if [[ -z "$path_flag" ]]; then
    # `off`, or a backend spelling this Gufo version does not know. Pass the
    # operator's list through untouched — the engine's own error beats a guess
    # from us — but say what we did NOT do, because an absent path flag is the
    # failure that looks exactly like "speculation is configured".
    if [[ -z "$backend" ]]; then
      printf 'gufo-serve.sh: GUFO_SPEC_ARGS carries no --speculative <backend>, so no draft path is appended\n'
    else
      printf 'gufo-serve.sh: unknown speculation backend %s — passing GUFO_SPEC_ARGS through unchanged\n' "$backend" >&2
    fi
    gufo_args+=("${spec[@]}")
  else
    hand_named=0
    for arg in "${spec[@]}"; do
      if [[ "$arg" == "$path_flag" ]]; then
        hand_named=1
      fi
    done
    if [[ "$hand_named" == "1" ]]; then
      printf 'gufo-serve.sh: %s is already in GUFO_SPEC_ARGS — not appending ours\n' "$path_flag"
      if [[ -n "$draft_rel" ]]; then
        run_args+=(-v "${draft_snapshot}:/draft:ro")
      fi
    elif [[ -z "$draft_rel" ]]; then
      # No draft to name. Serving without speculation is a slower success and a
      # much better outcome than the container exiting 2 on every load.
      printf 'gufo-serve.sh: %s needs a draft and nothing matched %s :: %s — serving WITHOUT speculation\n' \
        "$path_flag" "${GUFO_DRAFT_REPO:-the draft repo}" "${GUFO_DRAFT_PATTERN:-}" >&2
    else
      run_args+=(-v "${draft_snapshot}:/draft:ro")
      # The switch AND the file it switches on: `--speculative mtp` and
      # `--mtp-model /draft/...` are one recipe, not two options, and passing
      # only the path flag is the quietest failure this script could have —
      # Gufo accepts it, serves, and speculates about nothing.
      gufo_args+=("${spec[@]}" "$path_flag" "/draft/${draft_rel}")
      printf 'gufo-serve.sh: speculation on — %s\n' "${spec[*]}"
    fi
  fi
fi

if [[ -n "${HF_TOKEN:-}" ]]; then
  run_args+=(-e HF_TOKEN)
fi
if [[ -n "${CONTAINER_EXTRA_ARGS:-}" ]]; then
  # shellcheck disable=SC2206
  extra=(${CONTAINER_EXTRA_ARGS})
  run_args+=("${extra[@]}")
fi

# One-line budget note. This is the only thing the serve script prints besides
# the engine's own log: llama-swap captures stdout into the model's log, and a
# wall of text here buries the engine.
printf 'gufo-serve.sh: %s @ %s (port %s, context %s, container %s)\n' \
  "${GUFO_MODEL_NAME}" \
  "$(du -h -- "${snapshot}/${shard}" 2>/dev/null | cut -f1)" \
  "${PORT}" \
  "${GUFO_CONTEXT_LENGTH}" \
  "${CONTAINER_NAME}"

# Blocking, and exec'd: docker stop <name> then propagates here, the container
# exits, --rm removes it, and this process ends — which is exactly what
# llama-swap needs to see a clean unload.
exec "${CONTAINER_RUNTIME}" "${run_args[@]}" "${GUFO_IMAGE}" "${gufo_args[@]}"
